//! # `ResNetV2` prefabs

// The prefabs and the stage table between the `gen_resnetv2_prefabs`
// markers are generated by `tools/gen_resnetv2_prefabs.py` from timm's own
// `resnetv2.py` entrypoints and models; edit the script, not them.

use alloc::{
    vec,
    vec::Vec,
};

use crate::{
    data::pretrained::{
        PrefabTable,
        Prefabs,
    },
    kits::images::classification::resnetv2::{
        BIT_STD_CONV_EPSILON,
        ResNetV2ContractConfig,
        ResNetV2Norm,
        ResNetV2StemKind,
    },
};

impl ResNetV2ContractConfig {
    /// A `ResNetV2` of timm's defaults with 1000 classes: stages of `layers`
    /// units.
    fn resnetv2(layers: Vec<usize>) -> Self {
        Self::new(layers, 1000)
    }

    // gen_resnetv2_prefabs: begin fns
    /// The `resnetv2_18` prefab: `ResNetV2` `18`; batch norms, basic units.
    pub fn resnetv2_18() -> Self {
        Self::resnetv2(vec![2, 2, 2, 2])
            .with_channels(vec![64, 128, 256, 512])
            .with_norm_layer(ResNetV2Norm::BatchNorm)
            .with_basic(true)
            .with_bottle_ratio(1.0)
    }

    /// The `resnetv2_18d` prefab: `ResNetV2` `18d`; the `deep` stem, batch
    /// norms, basic units, average-pool shortcuts.
    pub fn resnetv2_18d() -> Self {
        Self::resnetv2(vec![2, 2, 2, 2])
            .with_channels(vec![64, 128, 256, 512])
            .with_stem_type(ResNetV2StemKind::Deep)
            .with_norm_layer(ResNetV2Norm::BatchNorm)
            .with_basic(true)
            .with_bottle_ratio(1.0)
            .with_avg_down(true)
    }

    /// The `resnetv2_34` prefab: `ResNetV2` `34`; batch norms, basic units.
    pub fn resnetv2_34() -> Self {
        Self::resnetv2(vec![3, 4, 6, 3])
            .with_channels(vec![64, 128, 256, 512])
            .with_norm_layer(ResNetV2Norm::BatchNorm)
            .with_basic(true)
            .with_bottle_ratio(1.0)
    }

    /// The `resnetv2_34d` prefab: `ResNetV2` `34d`; the `deep` stem, batch
    /// norms, basic units, average-pool shortcuts.
    pub fn resnetv2_34d() -> Self {
        Self::resnetv2(vec![3, 4, 6, 3])
            .with_channels(vec![64, 128, 256, 512])
            .with_stem_type(ResNetV2StemKind::Deep)
            .with_norm_layer(ResNetV2Norm::BatchNorm)
            .with_basic(true)
            .with_bottle_ratio(1.0)
            .with_avg_down(true)
    }

    /// The `resnetv2_50` prefab: `ResNetV2` `50`; batch norms.
    pub fn resnetv2_50() -> Self {
        Self::resnetv2(vec![3, 4, 6, 3]).with_norm_layer(ResNetV2Norm::BatchNorm)
    }

    /// The `resnetv2_50d_evos` prefab: `ResNetV2` `50d_evos`; the `deep` stem,
    /// `EvoNorm-S0`, average-pool shortcuts.
    pub fn resnetv2_50d_evos() -> Self {
        Self::resnetv2(vec![3, 4, 6, 3])
            .with_stem_type(ResNetV2StemKind::Deep)
            .with_norm_layer(ResNetV2Norm::EvoNormS0)
            .with_avg_down(true)
    }

    /// The `resnetv2_50d_gn` prefab: `ResNetV2` `50d_gn`; the `deep` stem,
    /// group norms, average-pool shortcuts.
    pub fn resnetv2_50d_gn() -> Self {
        Self::resnetv2(vec![3, 4, 6, 3])
            .with_stem_type(ResNetV2StemKind::Deep)
            .with_avg_down(true)
    }

    /// The `resnetv2_101` prefab: `ResNetV2` `101`; batch norms.
    pub fn resnetv2_101() -> Self {
        Self::resnetv2(vec![3, 4, 23, 3]).with_norm_layer(ResNetV2Norm::BatchNorm)
    }

    /// The `resnetv2_50x1_bit` prefab: `BiT` `50x1`; the `fixed` stem,
    /// weight-standardized convs, group norms.
    pub fn resnetv2_50x1_bit() -> Self {
        Self::resnetv2(vec![3, 4, 6, 3])
            .with_stem_type(ResNetV2StemKind::Fixed)
            .with_std_conv(Some(BIT_STD_CONV_EPSILON))
    }

    /// The `resnetv2_50x3_bit` prefab: `BiT` `50x3`; 3x wide, the `fixed` stem,
    /// weight-standardized convs, group norms.
    pub fn resnetv2_50x3_bit() -> Self {
        Self::resnetv2(vec![3, 4, 6, 3])
            .with_width_factor(3)
            .with_stem_type(ResNetV2StemKind::Fixed)
            .with_std_conv(Some(BIT_STD_CONV_EPSILON))
    }

    /// The `resnetv2_101x1_bit` prefab: `BiT` `101x1`; the `fixed` stem,
    /// weight-standardized convs, group norms.
    pub fn resnetv2_101x1_bit() -> Self {
        Self::resnetv2(vec![3, 4, 23, 3])
            .with_stem_type(ResNetV2StemKind::Fixed)
            .with_std_conv(Some(BIT_STD_CONV_EPSILON))
    }

    /// The `resnetv2_101x3_bit` prefab: `BiT` `101x3`; 3x wide, the `fixed`
    /// stem, weight-standardized convs, group norms.
    pub fn resnetv2_101x3_bit() -> Self {
        Self::resnetv2(vec![3, 4, 23, 3])
            .with_width_factor(3)
            .with_stem_type(ResNetV2StemKind::Fixed)
            .with_std_conv(Some(BIT_STD_CONV_EPSILON))
    }

    /// The `resnetv2_152x2_bit` prefab: `BiT` `152x2`; 2x wide, the `fixed`
    /// stem, weight-standardized convs, group norms.
    pub fn resnetv2_152x2_bit() -> Self {
        Self::resnetv2(vec![3, 8, 36, 3])
            .with_width_factor(2)
            .with_stem_type(ResNetV2StemKind::Fixed)
            .with_std_conv(Some(BIT_STD_CONV_EPSILON))
    }

    /// The `resnetv2_152x4_bit` prefab: `BiT` `152x4`; 4x wide, the `fixed`
    /// stem, weight-standardized convs, group norms.
    pub fn resnetv2_152x4_bit() -> Self {
        Self::resnetv2(vec![3, 8, 36, 3])
            .with_width_factor(4)
            .with_stem_type(ResNetV2StemKind::Fixed)
            .with_std_conv(Some(BIT_STD_CONV_EPSILON))
    }
    // gen_resnetv2_prefabs: end fns
}

/// The `ResNetV2` geometries by name, timm's architecture names: a
/// [`ResNetV2ContractConfig`] of 1000 classes for every architecture of
/// timm's `resnetv2.py` with hub weights: timm's own `ResNetV2`s and the
/// `BiT` towers.
///
/// A prefab has no weights: a timm row takes the classes from its
/// `config.json`.
impl Prefabs for ResNetV2ContractConfig {
    const PREFABS: PrefabTable<Self> = &[
        // gen_resnetv2_prefabs: begin table
        ("resnetv2_18", Self::resnetv2_18),
        ("resnetv2_18d", Self::resnetv2_18d),
        ("resnetv2_34", Self::resnetv2_34),
        ("resnetv2_34d", Self::resnetv2_34d),
        ("resnetv2_50", Self::resnetv2_50),
        ("resnetv2_50d_evos", Self::resnetv2_50d_evos),
        ("resnetv2_50d_gn", Self::resnetv2_50d_gn),
        ("resnetv2_101", Self::resnetv2_101),
        ("resnetv2_50x1_bit", Self::resnetv2_50x1_bit),
        ("resnetv2_50x3_bit", Self::resnetv2_50x3_bit),
        ("resnetv2_101x1_bit", Self::resnetv2_101x1_bit),
        ("resnetv2_101x3_bit", Self::resnetv2_101x3_bit),
        ("resnetv2_152x2_bit", Self::resnetv2_152x2_bit),
        ("resnetv2_152x4_bit", Self::resnetv2_152x4_bit),
        // gen_resnetv2_prefabs: end table
    ];
    const PREFAB_TABLE: &'static str = "resnetv2";
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::{
        blocks::{
            conv::ConvBlock2dMeta,
            images::models::conv_net::ConvChainMeta,
        },
        burner::module::ToStructureConfig,
    };

    /// Each architecture as timm builds it: its stem's conv widths, and each
    /// stage's `(depth, width, bottleneck width)`, read from timm's modules.
    #[allow(clippy::type_complexity)]
    const TIMM_STAGES: &[(&str, &[usize], [(usize, usize, usize); 4])] = &[
        // gen_resnetv2_prefabs: begin stages
        (
            "resnetv2_18",
            &[64],
            [(2, 64, 64), (2, 128, 128), (2, 256, 256), (2, 512, 512)],
        ),
        (
            "resnetv2_18d",
            &[32, 32, 64],
            [(2, 64, 64), (2, 128, 128), (2, 256, 256), (2, 512, 512)],
        ),
        (
            "resnetv2_34",
            &[64],
            [(3, 64, 64), (4, 128, 128), (6, 256, 256), (3, 512, 512)],
        ),
        (
            "resnetv2_34d",
            &[32, 32, 64],
            [(3, 64, 64), (4, 128, 128), (6, 256, 256), (3, 512, 512)],
        ),
        (
            "resnetv2_50",
            &[64],
            [(3, 256, 64), (4, 512, 128), (6, 1024, 256), (3, 2048, 512)],
        ),
        (
            "resnetv2_50d_evos",
            &[32, 32, 64],
            [(3, 256, 64), (4, 512, 128), (6, 1024, 256), (3, 2048, 512)],
        ),
        (
            "resnetv2_50d_gn",
            &[32, 32, 64],
            [(3, 256, 64), (4, 512, 128), (6, 1024, 256), (3, 2048, 512)],
        ),
        (
            "resnetv2_101",
            &[64],
            [(3, 256, 64), (4, 512, 128), (23, 1024, 256), (3, 2048, 512)],
        ),
        (
            "resnetv2_50x1_bit",
            &[64],
            [(3, 256, 64), (4, 512, 128), (6, 1024, 256), (3, 2048, 512)],
        ),
        (
            "resnetv2_50x3_bit",
            &[192],
            [
                (3, 768, 192),
                (4, 1536, 384),
                (6, 3072, 768),
                (3, 6144, 1536),
            ],
        ),
        (
            "resnetv2_101x1_bit",
            &[64],
            [(3, 256, 64), (4, 512, 128), (23, 1024, 256), (3, 2048, 512)],
        ),
        (
            "resnetv2_101x3_bit",
            &[192],
            [
                (3, 768, 192),
                (4, 1536, 384),
                (23, 3072, 768),
                (3, 6144, 1536),
            ],
        ),
        (
            "resnetv2_152x2_bit",
            &[128],
            [
                (3, 512, 128),
                (8, 1024, 256),
                (36, 2048, 512),
                (3, 4096, 1024),
            ],
        ),
        (
            "resnetv2_152x4_bit",
            &[256],
            [
                (3, 1024, 256),
                (8, 2048, 512),
                (36, 4096, 1024),
                (3, 8192, 2048),
            ],
        ),
        // gen_resnetv2_prefabs: end stages
    ];

    /// Every prefab's stem and stages are timm's.
    #[test]
    fn test_prefab_stages_are_timms() {
        assert_eq!(
            TIMM_STAGES.len(),
            ResNetV2ContractConfig::prefab_names().len()
        );
        for (name, stem, stages) in TIMM_STAGES {
            let structure = ResNetV2ContractConfig::expect_prefab(name)
                .try_to_structure()
                .unwrap_or_else(|e| panic!("{name}: {e}"));
            let ours: Vec<_> = structure
                .stem
                .convs
                .iter()
                .map(|c| c.out_channels())
                .collect();
            assert_eq!(&ours, stem, "{name}: the stem");
            let ours: Vec<_> = structure
                .stages
                .iter()
                .map(|s| {
                    let unit = &s.units[0];
                    (
                        s.units.len(),
                        unit.out_channels(),
                        unit.convs[0].out_channels(),
                    )
                })
                .collect();
            assert_eq!(ours, stages, "{name}");
        }
    }
}
